// ═══ CountDownLatch — "wait until N events complete" ═══
CountDownLatch latch = new CountDownLatch(3);  // 3 events

// 3 threads each do work and count down:
pool.submit(() -> { doTaskA(); latch.countDown(); });  // 3→2
pool.submit(() -> { doTaskB(); latch.countDown(); });  // 2→1
pool.submit(() -> { doTaskC(); latch.countDown(); });  // 1→0

latch.await();  // BLOCKS until count reaches 0!
// All 3 tasks guaranteed complete here!
generateFinalReport();
// ONE-TIME USE: once count reaches 0, latch stays at 0 forever. Can't reset.

// ═══ CyclicBarrier — "all N threads wait for each other" ═══
CyclicBarrier barrier = new CyclicBarrier(3, () -> {
    System.out.println("All 3 reached barrier — proceed to next phase!");
});

// 3 threads:
pool.submit(() -> { phase1(); barrier.await(); phase2(); });
pool.submit(() -> { phase1(); barrier.await(); phase2(); });
pool.submit(() -> { phase1(); barrier.await(); phase2(); });
// Each thread: does phase1 → waits at barrier → when ALL 3 arrive → all proceed to phase2!
// REUSABLE: barrier resets after each trip — can be used for multiple phases!

// ═══ COMPARISON ═══
// CountDownLatch:                     CyclicBarrier:
// One or many threads count down      All threads wait for each other
// Waiting thread ≠ counting threads   Waiting threads = same threads
// ONE-TIME (can't reset)              REUSABLE (auto-resets)
// "Wait for N events"                 "All N threads sync at a point"

// ═══ Semaphore — "limit concurrent access to N" ═══
Semaphore semaphore = new Semaphore(5);  // max 5 concurrent
semaphore.acquire();  // take a permit (blocks if none available)
try { accessLimitedResource(); }
finally { semaphore.release(); }  // return permit
// Like a parking lot with 5 spots — 6th car waits until one leaves!

// ═══ CONCURRENCY TOOLKIT SUMMARY ═══
// Tool               Purpose                          Example
// Thread/Runnable    Basic execution                  new Thread(task).start()
// ExecutorService    Pool management                  pool.submit(callable)
// synchronized       Mutual exclusion                 synchronized(lock) { }
// ReentrantLock      Flexible locking (tryLock)       lock.lock(); try {} finally { unlock }
// volatile           Visibility guarantee             volatile boolean flag
// AtomicInteger      Lock-free counter                counter.incrementAndGet()
// ConcurrentHashMap  Thread-safe map                  map.computeIfAbsent(k, fn)
// BlockingQueue      Producer-consumer                queue.put()/take()
// CountDownLatch     Wait for N completions           latch.await()
// CyclicBarrier      N threads sync at checkpoint     barrier.await()
// Semaphore          Limit concurrency to N           semaphore.acquire()
// CompletableFuture  Async pipeline                   cf.thenApply().thenAccept()
