// ─── File: src/test/java/com/bank/tools/ConcurrencyToolsTest.java ───
package com.bank.tools;

import org.junit.jupiter.api.Test;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;
import static org.assertj.core.api.Assertions.*;

class ConcurrencyToolsTest {

    // ═══ CountDownLatch: wait for N completions ═══
    @Test
    void countDownLatch_waitForAll() throws InterruptedException {
        CountDownLatch latch = new CountDownLatch(3);
        AtomicInteger completed = new AtomicInteger(0);
        ExecutorService pool = Executors.newFixedThreadPool(3);

        for (int i = 0; i < 3; i++) {
            pool.submit(() -> {
                completed.incrementAndGet();
                latch.countDown();
            });
        }

        latch.await(5, TimeUnit.SECONDS);
        assertThat(completed.get()).isEqualTo(3);  // all 3 done!
        pool.shutdown();
    }

    // ═══ CyclicBarrier: all threads sync at checkpoint ═══
    @Test
    void cyclicBarrier_syncAtCheckpoint() throws InterruptedException {
        int threads = 3;
        AtomicInteger phase1Done = new AtomicInteger(0);
        AtomicInteger phase2Done = new AtomicInteger(0);
        CyclicBarrier barrier = new CyclicBarrier(threads);
        CountDownLatch allDone = new CountDownLatch(threads);
        ExecutorService pool = Executors.newFixedThreadPool(threads);

        for (int i = 0; i < threads; i++) {
            pool.submit(() -> {
                try {
                    phase1Done.incrementAndGet();
                    barrier.await();  // ALL must reach here before ANY proceeds!
                    // Guaranteed: phase1Done == 3 at this point!
                    assertThat(phase1Done.get()).isEqualTo(3);
                    phase2Done.incrementAndGet();
                } catch (Exception e) { }
                allDone.countDown();
            });
        }

        allDone.await(5, TimeUnit.SECONDS);
        assertThat(phase2Done.get()).isEqualTo(3);
        pool.shutdown();
    }

    // ═══ Semaphore: limit concurrent access ═══
    @Test
    void semaphore_limitConcurrency() throws InterruptedException {
        Semaphore semaphore = new Semaphore(2);  // max 2 concurrent!
        AtomicInteger maxConcurrent = new AtomicInteger(0);
        AtomicInteger currentConcurrent = new AtomicInteger(0);
        CountDownLatch done = new CountDownLatch(10);
        ExecutorService pool = Executors.newFixedThreadPool(10);

        for (int i = 0; i < 10; i++) {
            pool.submit(() -> {
                try {
                    semaphore.acquire();
                    int current = currentConcurrent.incrementAndGet();
                    maxConcurrent.updateAndGet(max -> Math.max(max, current));
                    Thread.sleep(50);
                    currentConcurrent.decrementAndGet();
                } catch (InterruptedException e) { }
                finally {
                    semaphore.release();
                    done.countDown();
                }
            });
        }

        done.await(10, TimeUnit.SECONDS);
        assertThat(maxConcurrent.get()).isLessThanOrEqualTo(2);  // never > 2!
        pool.shutdown();
    }

    // ═══ CountDownLatch is ONE-TIME ═══
    @Test
    void countDownLatch_cannotReset() throws InterruptedException {
        CountDownLatch latch = new CountDownLatch(1);
        latch.countDown();  // count = 0
        latch.await();      // returns immediately (already 0)

        latch.countDown();  // no effect! Count stays at 0.
        assertThat(latch.getCount()).isEqualTo(0);
        // Can't reset! Must create a new CountDownLatch.
    }

    // ═══ CyclicBarrier IS reusable ═══
    @Test
    void cyclicBarrier_reusable() throws Exception {
        CyclicBarrier barrier = new CyclicBarrier(2);

        // Trip 1:
        Thread t1 = new Thread(() -> { try { barrier.await(); } catch (Exception e) {} });
        t1.start();
        barrier.await();  // both arrive → trip 1 complete
        t1.join();

        // Trip 2 (reused!):
        Thread t2 = new Thread(() -> { try { barrier.await(); } catch (Exception e) {} });
        t2.start();
        barrier.await();  // both arrive → trip 2 complete
        t2.join();
        // Barrier auto-reset after each trip!
    }
}
